/* Site search: matches the text in assets/search-index.js (generated by build.ps1) entirely in the browser.

   - Reads no URL parts, writes no storage, makes no network call; the index is loaded by a normal <script> tag.
   - Matching ignores Arabic diacritics, tatweel, hamza forms (alef), ta marbuta/ha, alef maqsura/ya and digit shapes.
   - Every value from the index is shown with textContent (never as HTML); the page path and section id are checked
     against a strict pattern before they are used to build a link. */
(function () {
  'use strict';

  var DATA = window.BM_SEARCH;
  var form = document.getElementById('search-form');
  var input = document.getElementById('q');
  var list = document.getElementById('results');
  var status = document.getElementById('status');
  if (!DATA || !form || !input || !list || !status) { return; }

  var ROOT = '../';                         // this page lives in search/, one level below the site root
  var PATH_RE = /^[A-Za-z0-9_\/.-]+\.html$/;
  var ANCHOR_RE = /^[A-Za-z0-9_-]*$/;
  var MAX_RESULTS = 40;
  var DIGITS = '٠١٢٣٤٥٦٧٨٩';

  var wordChar;
  try { wordChar = new RegExp('[\\p{L}\\p{N}]', 'u'); } catch (e) { wordChar = /[A-Za-z0-9؀-ۿ]/; }

  var FOLD = { 'أ': 'ا', 'إ': 'ا', 'آ': 'ا', 'ٱ': 'ا', 'ى': 'ي', 'ة': 'ه', 'ؤ': 'و', 'ئ': 'ي' };

  function arabic(n) {
    return String(n).replace(/[0-9]/g, function (d) { return DIGITS.charAt(Number(d)); });
  }

  // Normalised copy of a text plus, for every normalised character, where it came from in the original (to highlight).
  function fold(text) {
    var out = [];
    var map = [];
    var lastSpace = true;
    for (var i = 0; i < text.length; i++) {
      var ch = text.charAt(i);
      var c = text.charCodeAt(i);
      if ((c >= 0x064B && c <= 0x065F) || c === 0x0670 || c === 0x0640 || (c >= 0x06D6 && c <= 0x06ED)) { continue; }
      if (FOLD[ch]) { ch = FOLD[ch]; }
      else if (c >= 0x0660 && c <= 0x0669) { ch = String(c - 0x0660); }
      else if (c >= 0x06F0 && c <= 0x06F9) { ch = String(c - 0x06F0); }
      else { ch = ch.toLowerCase(); }
      if (!wordChar.test(ch)) {
        if (lastSpace) { continue; }
        ch = ' ';
        lastSpace = true;
      } else {
        lastSpace = false;
      }
      out.push(ch);
      map.push(i);
    }
    return { s: out.join(''), map: map };
  }

  var entries = DATA.filter(function (e) {
    return e && typeof e.p === 'string' && typeof e.t === 'string' && typeof e.s === 'string' &&
      typeof e.a === 'string' && typeof e.x === 'string' && PATH_RE.test(e.p) && ANCHOR_RE.test(e.a);
  }).map(function (e, index) {
    return { e: e, order: index, n: fold(e.x).s, h: fold(e.s).s, t: fold(e.t).s };
  });

  function count(haystack, needle) {
    var found = 0;
    var from = 0;
    while (found < 5) {
      var at = haystack.indexOf(needle, from);
      if (at < 0) { break; }
      found += 1;
      from = at + needle.length;
    }
    return found;
  }

  function search(tokens, phrase) {
    var hits = [];
    entries.forEach(function (item) {
      var score = 0;
      for (var i = 0; i < tokens.length; i++) {
        var tok = tokens[i];
        var inBody = item.n.indexOf(tok) >= 0;
        var inHead = item.h.indexOf(tok) >= 0;
        var inTitle = item.t.indexOf(tok) >= 0;
        if (!inBody && !inHead && !inTitle) { return; }
        score += (inHead ? 6 : 0) + (inTitle ? 2 : 0) + (inBody ? count(item.n, tok) : 0);
      }
      if (tokens.length > 1 && (item.n.indexOf(phrase) >= 0 || item.h.indexOf(phrase) >= 0)) { score += 8; }
      hits.push({ item: item, score: score });
    });
    hits.sort(function (a, b) { return b.score - a.score || a.item.order - b.item.order; });
    return hits;
  }

  // Build the snippet (original text around the first match) with the matched words wrapped in <mark>.
  function snippet(item, tokens, phrase) {
    var text = item.e.x;
    var f = fold(text);
    var at = -1;
    if (tokens.length > 1) { at = f.s.indexOf(phrase); }
    if (at < 0) {
      tokens.forEach(function (tok) {
        var p = f.s.indexOf(tok);
        if (p >= 0 && (at < 0 || p < at)) { at = p; }
      });
    }
    var from = 0;
    if (at > 60) {
      from = Math.max(0, f.map[at] - 60);
      var startSpace = text.indexOf(' ', from);                       // begin at a word start, not mid-word
      if (startSpace >= 0 && startSpace - from < 15 && startSpace < f.map[at]) { from = startSpace + 1; }
    }
    var to = Math.min(text.length, from + 190);
    var endSpace = text.indexOf(' ', to);                               // end at a word end, not mid-word
    if (endSpace >= 0 && endSpace - to < 25) { to = endSpace; } else if (endSpace < 0) { to = text.length; }
    var ranges = [];
    tokens.forEach(function (tok) {
      var p = f.s.indexOf(tok);
      while (p >= 0) {
        var start = f.map[p];
        var end = f.map[p + tok.length - 1] + 1;
        if (start >= to) { break; }
        if (end > from) { ranges.push([Math.max(start, from), Math.min(end, to)]); }
        p = f.s.indexOf(tok, p + tok.length);
      }
    });
    ranges.sort(function (a, b) { return a[0] - b[0]; });
    var merged = [];
    ranges.forEach(function (r) {
      var last = merged[merged.length - 1];
      if (last && r[0] <= last[1]) { last[1] = Math.max(last[1], r[1]); } else { merged.push([r[0], r[1]]); }
    });

    var box = document.createElement('span');
    box.className = 'hit-snip';
    if (from > 0) { box.appendChild(document.createTextNode('… ')); }
    var cursor = from;
    merged.forEach(function (r) {
      if (r[0] > cursor) { box.appendChild(document.createTextNode(text.slice(cursor, r[0]))); }
      var mark = document.createElement('mark');
      mark.textContent = text.slice(r[0], r[1]);
      box.appendChild(mark);
      cursor = r[1];
    });
    if (cursor < to) { box.appendChild(document.createTextNode(text.slice(cursor, to))); }
    if (to < text.length) { box.appendChild(document.createTextNode(' …')); }
    return box;
  }

  function clear() {
    while (list.firstChild) { list.removeChild(list.firstChild); }
  }

  function render() {
    clear();
    var query = fold(input.value).s.trim();
    var tokens = [];
    query.split(' ').forEach(function (t) { if (t.length >= 2 && tokens.indexOf(t) < 0) { tokens.push(t); } });
    if (tokens.length === 0) {
      status.textContent = query ? 'اكتب كلمة من حرفين فأكثر.' : '';
      return;
    }
    var phrase = tokens.join(' ');
    var hits = search(tokens, phrase);
    if (hits.length === 0) {
      status.textContent = 'لا توجد نتائج. جرّب كلمة أقصر أو صيغةً أخرى للكلمة.';
      return;
    }
    status.textContent = hits.length > MAX_RESULTS
      ? arabic(hits.length) + ' نتيجة، وهذه أفضل ' + arabic(MAX_RESULTS) + ': ضيّق البحث بكلمة أخرى.'
      : arabic(hits.length) + ' نتيجة';
    hits.slice(0, MAX_RESULTS).forEach(function (hit) {
      var e = hit.item.e;
      var li = document.createElement('li');
      var a = document.createElement('a');
      a.className = 'hit';
      a.href = ROOT + e.p + (e.a ? '#' + e.a : '');
      var page = document.createElement('span');
      page.className = 'hit-page';
      page.textContent = e.t;
      var sec = document.createElement('strong');
      sec.className = 'hit-sec';
      sec.textContent = e.s || 'مقدمة الصفحة';
      a.appendChild(page);
      a.appendChild(sec);
      a.appendChild(snippet(hit.item, tokens, phrase));
      li.appendChild(a);
      list.appendChild(li);
    });
  }

  form.addEventListener('submit', function (event) { event.preventDefault(); render(); });
  input.addEventListener('input', render);
  input.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') { input.value = ''; render(); }
  });
  input.focus();
})();
